/// <summary>
/// Standard cost version Process - Create standard cost versions and claim lines
/// Batch controller class extends SysOperationServiceController
/// </summary>
[
    SysOperationJournaledParametersAttribute(true)
]
public class METStandardCostProcessController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
    /// <summary>
    /// Caption visible
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METStandardCostProcessService));
        this.parmMethodName(methodStr(METStandardCostProcessService, processOperation));
        this.parmDialogCaption(this.caption());
    }

/// <summary>
/// Automatically populates the batch text required by user before submitting to batch
/// </summary>
/// <returns>caption</returns>
public ClassDescription caption()
{
    return "@MET:StandardCostGenerateLabel";
}

    /// <summary>
    /// Main method required to run the opration
    /// </summary>
    /// <param name = "args">Args</param>
    public static void main(Args args)
    {
        METStandardCostProcessController controller;

        controller = new METStandardCostProcessController();
        controller.parmArgs(args);

        controller.startOperation();
        
    }

/// <summary>
/// BP to have a constructor for new controller.
/// </summary>
/// <returns>Controller instance</returns>
public static METStandardCostProcessController construct()
{
    return new METStandardCostProcessController();
}

/// <summary>
/// Control whether batch task should retry in case of SQL transient errors.
/// </summary>
/// <returns>true if task should be retried; otherwise, false.</returns>
public boolean isRetryable()
{
    return true;
}
